import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Управление набором модов","description":"","frontmatter":{"pageId":"admins/modpacks","contentRevision":1},"headers":[],"relativePath":"ru/admins/modpacks.md","filePath":"ru/admins/modpacks.md"}'),l={name:"ru/admins/modpacks.md"};function o(s,a,d,n,c,m){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="управление-набором-модов" tabindex="-1">Управление набором модов <a class="header-anchor" href="#управление-набором-модов" aria-label="Permalink to &quot;Управление набором модов&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><ol><li>Подготовь проверенный набор в отдельной установке игры. Зафиксируй ModsConfig.xml, порядок, версии и hash.</li><li>Выполни modpack import --from &lt;ModsConfig.xml&gt; --mods-dir &lt;folders&gt; --dry-run. После проверки добавь --server/--token для отправки требований.</li><li>modpack defs собирает разрешённые ThingDef/PawnKindDef; пустой список выключает эту проверку. Общие настройки импортируются только для выбранных --mod, загружаемых ниже Rimlink.</li><li>Для серверной доставки выполни modpack package requirements --output &lt;new-file&gt;, затем package pack --source &lt;redistributable-folders&gt; --requirements &lt;file&gt; --output &lt;new-directory&gt;.</li><li>Проверь archive.zip и manifest.json, лицензии и настройки. package publish --from &lt;directory&gt; требует --confirm-redistribution; --confirm-public и --confirm-shared-settings подтверждают соответствующее раскрытие. Проверь package status; unpublish снимает публикацию.</li></ol><p>Протестируй чистого клиента после изменения коллекции.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не упаковывай каталог игры, Core/DLC и секреты модов. Pack требует полный подготовленный набор и новый output. Публикация — отдельное внешнее действие оператора. Изменение требований может сделать прежний опубликованный пакет неактуальным.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./cli">Справочник CLI</a></li><li><a href="./../players/modpacks">Набор модов сервера</a></li><li><a href="./updating">Обновление сервера и клиентов</a></li></ul>',9)])])}const h=e(l,[["render",o]]);export{u as __pageData,h as default};
